from collections import Counter


def _words(text):
    word = []
    for ch in text:
        if ch.isalnum():
            word.append(ch.lower())
        elif word:
            yield "".join(word)
            word = []
    if word:
        yield "".join(word)


def top_n(text, n):
    if n <= 0:
        return []
    counts = Counter(_words(text))
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return ranked[:n]
